<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref } from 'vue'
import { request } from '../api/http'
import { session } from '../session'
import { stateLabel } from '../api/manuscripts'
import { stateNames,actionNames } from '../api/training'
import ExperimentChart from '../components/experiments/ExperimentChart.vue'
interface Dashboard { generatedAt:string;scope:string;counts:Record<string,number>;statusDistribution:Array<{status:string;count:number}>;trend:Array<{date:string;submissions:number;runs:number}>;recent:Array<{id:string;title:string;status:string;updatedAt:string;submissionId?:string}>;runs?:Array<{id:string;action:string;status:string;title:string;createdAt:string}> }
const data=ref<Dashboard>(),error=ref(''),loading=ref(true);let timer:ReturnType<typeof setInterval>|undefined,alive=true,refreshing=false
const member=computed(()=>session.user?.role==='MEMBER'),admin=computed(()=>session.user?.role==='ADMIN')
const stats=computed(()=>member.value?[['manuscripts','部门稿件','/manuscripts'],['pending','待审核','/manuscripts'],['published','已发布','/publications'],['checks','稿件检查','/workspace/content']]:[['pending','待审核',admin.value?'/system?tab=tasks':'/reviews'],['datasets','可用数据集','/datasets'],['models','已训练模型','/models'],['activeRuns','数据与训练任务','/training']])
const cards=computed(()=>[
  {title:'文本复用检测',hint:'比对历史稿件，定位重复片段。',panel:'content',tag:'字面匹配'},
  {title:'语义改写检测',hint:'查找表达不同、语义相近的内容。',panel:'content',tag:'语义证据'},
  {title:'图片复用检测',hint:'比对相似配图，查看来源。',panel:'content',tag:'图片证据'},
  {title:'图片文字识别',hint:'识别图片文字，辅助内容核对。',panel:'content',tag:'OCR'},
  {title:'语法检查',hint:'检查错字、重复和语法，逐条处理建议。',panel:'grammar',tag:'规则 + 模型'},
  {title:'图文一致性',hint:'查找关联段落，对照图片中的事实字段。',panel:'image',tag:'图文 + OCR'},
])
const destination=(panel:string)=>member.value?`/workspace/${panel}`:admin.value?'/system?tab=tasks':'/reviews'
const series=computed(()=>({tooltip:{trigger:'axis',borderRadius:0},legend:{data:member.value?['送审稿件']:['送审稿件','数据与训练任务']},grid:{left:45,right:20,top:40,bottom:55},xAxis:{type:'category',data:data.value?.trend.map(v=>v.date.slice(5))},yAxis:{type:'value',minInterval:1,name:'数量'},dataZoom:[{type:'inside'},{type:'slider',height:16,bottom:6}],series:[{name:'送审稿件',type:'line',data:data.value?.trend.map(v=>v.submissions)},...(!member.value?[{name:'数据与训练任务',type:'line',data:data.value?.trend.map(v=>v.runs)}]:[])]}))
const distribution=computed(()=>({tooltip:{trigger:'axis',borderRadius:0},grid:{left:45,right:20,top:25,bottom:35},xAxis:{type:'category',data:data.value?.statusDistribution.map(v=>stateLabel[v.status]??v.status)},yAxis:{type:'value',minInterval:1,name:'篇'},series:[{type:'bar',barMaxWidth:45,data:data.value?.statusDistribution.map(v=>v.count)}]}))
async function load(){if(refreshing)return;refreshing=true;try{const result=await request<Dashboard>('/api/dashboard');if(alive){data.value=result;error.value=''}}catch(value){if(alive)error.value=value instanceof Error?value.message:'读取首页失败'}finally{loading.value=false;refreshing=false}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),10000)});onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer)})
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})
</script>
<template><div class="home-page" v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="home-intro panel"><div><span class="eyebrow">南京传媒学院 · {{data?.scope || '工作台'}}</span><h2>{{session.user?.displayName}}，欢迎回来</h2><p class="muted">{{member?'编写一份稿件，完成内容、语法和图文检查。':'查看稿件处理、数据准备与模型训练进展。'}}</p></div><div class="intro-actions"><RouterLink v-if="member" to="/manuscripts/new"><el-button type="primary">新建稿件</el-button></RouterLink><RouterLink v-else to="/datasets"><el-button type="primary">进入数据中心</el-button></RouterLink><el-button @click="load">刷新</el-button></div></section>
<div class="home-stats"><RouterLink v-for="[key,label,to] in stats" :key="key" :to="to!"><span>{{label}}</span><strong>{{data?.counts[key!]?.toLocaleString() ?? '—'}}</strong><small>查看明细 →</small></RouterLink></div>
<section class="panel"><div class="section-heading"><h2>图文审核功能</h2><span class="muted">{{member?'沿用当前稿件':'按角色进入操作工作台'}}</span></div><div class="feature-grid"><RouterLink v-for="(card,index) in cards" :key="card.title" :to="destination(card.panel)" class="feature-card"><div class="feature-top"><span class="feature-number">0{{index+1}}</span><el-tag size="small" effect="plain">{{card.tag}}</el-tag></div><h3>{{card.title}}</h3><p>{{card.hint}}</p><span class="feature-action">{{member?'进入检查':admin?'查看检查任务':'进入审核工作台'}} →</span></RouterLink></div><div class="future-feature"><strong>事实一致性核验</strong><el-tag size="small" type="info">规划中</el-tag><span class="muted">核对外部证据来源与稿件事实。</span></div></section>
<div v-if="data" class="home-charts"><section class="panel"><ExperimentChart title="近14日处理趋势" :option="series as any"/></section><section class="panel"><ExperimentChart title="稿件状态分布" :option="distribution as any"/></section></div>
<section v-if="!admin" class="panel"><div class="section-heading"><h2>{{member?'近期稿件':'待审核稿件'}}</h2><RouterLink :to="member?'/manuscripts':'/reviews'">查看全部 →</RouterLink></div><el-table :data="data?.recent ?? []" empty-text="暂无稿件"><el-table-column prop="title" label="稿件" min-width="240"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{stateLabel[row.status]}}</el-tag></template></el-table-column><el-table-column label="更新时间" min-width="170"><template #default="{row}">{{time(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><RouterLink :to="!member?`/reviews/${row.id}`:['DRAFT','RETURNED'].includes(row.status)?`/manuscripts/${row.id}/edit`:`/manuscripts/${row.id}/history`">{{!member?'审核':['DRAFT','RETURNED'].includes(row.status)?'编辑':'查看'}}</RouterLink></template></el-table-column></el-table></section>
<section v-if="!member" class="panel"><div class="section-heading"><h2>数据与训练任务</h2><RouterLink to="/training">查看运行记录 →</RouterLink></div><el-table :data="data?.runs ?? []" empty-text="暂无任务"><el-table-column prop="title" label="数据集" min-width="220"/><el-table-column label="任务" min-width="130"><template #default="{row}">{{actionNames[row.action] || (row.action==='CLEAN'?'数据清洗':'质量评估')}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='FAILED'?'danger':row.status==='RUNNING'?'warning':'info'">{{stateNames[row.status] || row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><RouterLink :to="['AUDIT','CLEAN'].includes(row.action)?'/datasets':`/training?run=${row.id}`">查看</RouterLink></template></el-table-column></el-table></section><p v-if="data" class="updated-note muted">更新于 {{time(data.generatedAt)}} · 每10秒刷新</p></div></template>
<style scoped>.home-intro{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:24px}.home-intro h2{font-size:24px;margin:8px 0}.home-intro p{margin:0;line-height:1.8}.intro-actions{display:flex;gap:12px}.home-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.home-stats>a{background:var(--canvas);border:1px solid var(--line);border-top:3px solid var(--el-color-primary);padding:20px;text-decoration:none;color:inherit}.home-stats span,.home-stats small{display:block;color:var(--muted)}.home-stats strong{display:block;font-size:36px;margin:10px 0;color:var(--el-color-primary)}.home-stats small{font-size:12px}.feature-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.feature-card{padding:20px;border:1px solid var(--line);background:color-mix(in srgb,var(--el-color-primary) 3%,var(--canvas));text-decoration:none;color:inherit}.feature-card:hover,.feature-card:focus-visible{border-color:var(--el-color-primary);outline:2px solid var(--el-color-primary);outline-offset:2px}.feature-top{display:flex;justify-content:space-between;align-items:center}.feature-number{font-size:22px;font-weight:700;color:var(--el-color-primary)}.feature-card h3{font-size:18px;margin:18px 0 8px}.feature-card p{font-size:13px;color:var(--muted);line-height:1.8;min-height:24px}.feature-action{font-size:13px;color:var(--el-color-primary)}.future-feature{display:flex;gap:12px;align-items:center;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:16px;margin-top:16px;font-size:13px}.home-charts{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:14px}.updated-note{text-align:right;font-size:12px}@media(max-width:1050px){.feature-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.home-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.home-charts{grid-template-columns:1fr}}@media(max-width:650px){.feature-grid{grid-template-columns:1fr}.home-intro{align-items:flex-start;flex-direction:column}.home-stats>a{padding:14px}.home-stats strong{font-size:28px}}</style>
